const AuthContext = React.createContext(null);

function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const login = (name) => setUser({ name });
  const logout = () => setUser(null);
  return (
    <AuthContext.Provider value={{ user, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

function Login() {
  const { login } = React.useContext(AuthContext);
  const [name, setName] = useState('');
  return (
    <div style={{ padding: 16, fontFamily: 'system-ui' }}>
      <h3>Sign in</h3>
      <input value={name} onChange={e => setName(e.target.value)} placeholder="Your name" />
      <button onClick={() => login(name || 'Admin')} style={{ marginLeft: 8 }}>Log in</button>
    </div>
  );
}

function Protected({ children }) {
  const { user } = React.useContext(AuthContext);
  if (!user) return <Login />;
  return children;
}

function Dashboard() {
  const { user, logout } = React.useContext(AuthContext);
  return (
    <div style={{ padding: 16, fontFamily: 'system-ui' }}>
      <h2>Welcome, {user.name}</h2>
      <button onClick={logout}>Log out</button>
    </div>
  );
}

function App() {
  return (
    <AuthProvider>
      <Protected><Dashboard /></Protected>
    </AuthProvider>
  );
}

const USERS = [
  { id: 1, name: 'Ada Lovelace', email: 'ada@dash.io', role: 'Admin', status: 'active' },
  { id: 2, name: 'Alan Turing', email: 'alan@dash.io', role: 'Editor', status: 'inactive' },
  { id: 3, name: 'Grace Hopper', email: 'grace@dash.io', role: 'Admin', status: 'active' },
  { id: 4, name: 'Linus Torvalds', email: 'linus@dash.io', role: 'Viewer', status: 'active' },
  { id: 5, name: 'Margaret Hamilton', email: 'maggie@dash.io', role: 'Editor', status: 'inactive' }
];

function App() {
  const [query, setQuery] = useState('');
  const [status, setStatus] = useState('all');
  const [sortBy, setSortBy] = useState('name');
  const [selected, setSelected] = useState(() => new Set());

  const rows = React.useMemo(() => {
    const q = query.trim().toLowerCase();
    return USERS
      .filter(u => status === 'all' || u.status === status)
      .filter(u => !q || u.name.toLowerCase().includes(q) || u.email.toLowerCase().includes(q))
      .sort((a, b) => String(a[sortBy]).localeCompare(String(b[sortBy])));
  }, [query, status, sortBy]);

  const toggle = (id) => setSelected(prev => {
    const next = new Set(prev);
    next.has(id) ? next.delete(id) : next.add(id);
    return next;
  });
  const allShown = rows.length > 0 && rows.every(r => selected.has(r.id));
  const toggleAll = () => setSelected(prev => {
    const next = new Set(prev);
    if (allShown) rows.forEach(r => next.delete(r.id));
    else rows.forEach(r => next.add(r.id));
    return next;
  });

  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <div style={{ display: 'flex', gap: 8, marginBottom: 12, flexWrap: 'wrap' }}>
        <input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search name or email" />
        <select value={status} onChange={e => setStatus(e.target.value)}>
          <option value="all">All</option>
          <option value="active">Active</option>
          <option value="inactive">Inactive</option>
        </select>
        <select value={sortBy} onChange={e => setSortBy(e.target.value)}>
          <option value="name">Sort by name</option>
          <option value="role">Sort by role</option>
          <option value="status">Sort by status</option>
        </select>
        <span style={{ alignSelf: 'center' }}>{selected.size} selected</span>
      </div>
      <table style={{ borderCollapse: 'collapse', width: '100%' }}>
        <thead>
          <tr style={{ textAlign: 'left', borderBottom: '2px solid #ccc' }}>
            <th><input type="checkbox" checked={allShown} onChange={toggleAll} /></th>
            <th>Name</th><th>Email</th><th>Role</th><th>Status</th>
          </tr>
        </thead>
        <tbody>
          {rows.map(u => (
            <tr key={u.id} style={{ borderBottom: '1px solid #eee', background: selected.has(u.id) ? '#eef6ff' : 'transparent' }}>
              <td><input type="checkbox" checked={selected.has(u.id)} onChange={() => toggle(u.id)} /></td>
              <td>{u.name}</td>
              <td>{u.email}</td>
              <td>{u.role}</td>
              <td>{u.status}</td>
            </tr>
          ))}
          {rows.length === 0 && (
            <tr><td colSpan={5} style={{ padding: 12, color: '#888' }}>No users match.</td></tr>
          )}
        </tbody>
      </table>
    </div>
  );
}

