  { id: 4, name: 'Linus', role: 'Viewer' },
  { id: 5, name: 'Margaret', role: 'Editor' }
];
const PAGE_SIZE = 2;

function App() {
  const [query, setQuery] = useState('');
  const [page, setPage] = useState(0);

  const filtered = React.useMemo(() =>
    USERS.filter(u => u.name.toLowerCase().includes(query.toLowerCase())),
  [query]);

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount - 1);
  const pageRows = filtered.slice(safePage * PAGE_SIZE, safePage * PAGE_SIZE + PAGE_SIZE);

  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <input value={query} onChange={e => { setQuery(e.target.value); setPage(0); }} placeholder="Search" />
      <ul>{pageRows.map(u => <li key={u.id}>{u.name} - {u.role}</li>)}</ul>
      <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
        <button disabled={safePage === 0} onClick={() => setPage(p => p - 1)}>Prev</button>
        <span>Page {safePage + 1} of {pageCount}</span>
        <button disabled={safePage >= pageCount - 1} onClick={() => setPage(p => p + 1)}>Next</button>
      </div>
    </div>
  );
}

